from pico_ioc import component
from pico_caching import cacheable


@component
class PriceFeed:
    """Pretends to be a slow upstream: every call is a round trip you pay for."""

    def __init__(self):
        self.calls = 0

    # TODO: the same sku should not cost two round trips.
    def price(self, sku: str) -> float:
        self.calls += 1
        return 10.0 + len(sku)

