from pico_ioc import component
from pico_caching import cacheable


@component
class Quotes:
    def __init__(self):
        self.calls = 0

    # The default key is built from the arguments, so these two calls are
    # different entries even though the answer is the same.
    # TODO: make both spellings of the currency share one entry.
    @cacheable
    def rate(self, currency: str) -> float:
        self.calls += 1
        return 1.08

