from pico_ioc import component
from pico_caching import cacheable


@component
class Quotes:
    def __init__(self):
        self.calls = 0

    @cacheable(key=lambda currency: currency.upper())
    def rate(self, currency: str) -> float:
        self.calls += 1
        return 1.08

